 *   pnpm supabase db query --linked -f supabase/seeds/demo-catalogs.sql
 *
 * Remove the data with supabase/seeds/remove-demo-catalogs.sql.
 * Generated by supabase/seeds/generate_demo_catalogs.py.
 */

